"""Public API tests for the demo package: env-var detection + --demo flag."""

from __future__ import annotations

import pytest

from aws_tui.demo import DEMO_ENV_VAR, is_demo_mode_enabled


@pytest.mark.parametrize("value", ["1", "true", "TRUE", "True", "yes", "YES"])
def test_truthy_env_values_enable_demo(monkeypatch: pytest.MonkeyPatch, value: str) -> None:
    monkeypatch.setenv(DEMO_ENV_VAR, value)
    assert is_demo_mode_enabled(argv=["aws-tui"]) is True


@pytest.mark.parametrize("value", ["", "0", "false", "no", "off", "junk"])
def test_falsy_env_values_disable_demo(monkeypatch: pytest.MonkeyPatch, value: str) -> None:
    monkeypatch.setenv(DEMO_ENV_VAR, value)
    assert is_demo_mode_enabled(argv=["aws-tui"]) is False


def test_demo_cli_flag_enables_demo(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.delenv(DEMO_ENV_VAR, raising=False)
    assert is_demo_mode_enabled(argv=["aws-tui", "--demo"]) is True


def test_both_env_var_and_flag_enable_demo(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setenv(DEMO_ENV_VAR, "1")
    assert is_demo_mode_enabled(argv=["aws-tui", "--demo"]) is True


def test_no_signal_disables_demo(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.delenv(DEMO_ENV_VAR, raising=False)
    assert is_demo_mode_enabled(argv=["aws-tui"]) is False


def test_env_var_name_constant_is_canonical() -> None:
    assert DEMO_ENV_VAR == "AWS_TUI_DEMO"

from __future__ import annotations

import threading

import pytest

from tests.integration.conftest import _s3_compat_unavailable, _start_s3mock_or_unavailable
from tests.unit.domain.conftest import _start_moto_server


def test_s3mock_unavailability_fails_the_ci_gate(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setenv("CI", "true")

    with pytest.raises(pytest.fail.Exception, match="S3Mock unavailable"):
        _s3_compat_unavailable("S3Mock unavailable")


def test_s3mock_unavailability_skips_an_optional_local_run(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.delenv("CI", raising=False)

    with pytest.raises(pytest.skip.Exception, match="S3Mock unavailable"):
        _s3_compat_unavailable("S3Mock unavailable")


@pytest.mark.parametrize("ci", [False, True])
def test_failed_s3mock_startup_stops_partial_container(
    monkeypatch: pytest.MonkeyPatch, ci: bool
) -> None:
    class _PartialContainer:
        def __init__(self) -> None:
            self.stopped = False

        def start(self) -> None:
            raise RuntimeError("readiness failed")

        def stop(self) -> None:
            self.stopped = True

    if ci:
        monkeypatch.setenv("CI", "true")
        expected = pytest.fail.Exception
    else:
        monkeypatch.delenv("CI", raising=False)
        expected = pytest.skip.Exception
    container = _PartialContainer()

    with pytest.raises(expected, match="readiness failed"):
        _start_s3mock_or_unavailable(container)

    assert container.stopped is True


def test_moto_startup_has_a_hard_timeout() -> None:
    release = threading.Event()

    class _BlockedServer:
        def start(self) -> None:
            release.wait()

    try:
        with pytest.raises(RuntimeError, match="did not become ready"):
            _start_moto_server(_BlockedServer(), timeout=0.01)  # type: ignore[arg-type]
    finally:
        release.set()


def test_moto_startup_propagates_worker_failure() -> None:
    class _FailedServer:
        def start(self) -> None:
            raise OSError("bind failed")

    with pytest.raises(RuntimeError, match="bind failed"):
        _start_moto_server(_FailedServer(), timeout=0.1)  # type: ignore[arg-type]
